import sys
import heapq

def dijkstra(graph, start):
    queue = [(0, start)]
    visited = set()
    distances = {node: float('inf') for node in graph}
    distances[start] = 0

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        if current_node in visited:
            continue

        visited.add(current_node)

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(queue, (distance, neighbor))

    return distances

def can_cross_laser(time, a, b):
    cycle = a + b
    charge_end = (time // cycle) * cycle + a
    return time <= charge_end

def main():
    import sys
    input = sys.stdin.read().split()

    a = int(input[0])
    b = int(input[1])

    Ax = int(input[2])
    Ay = int(input[3])
    Bx = int(input[4])
    By = int(input[5])

    n = int(input[6])

    trenches = []
    for i in range(n):
        x1 = int(input[7 + i * 4])
        y1 = int(input[8 + i * 4])
        x2 = int(input[9 + i * 4])
        y2 = int(input[10 + i * 4])
        trenches.append((x1, y1, x2, y2))

    nodes = set()
    nodes.add((Ax, Ay))
    nodes.add((Bx, By))
    for x1, y1, x2, y2 in trenches:
        nodes.add((x1, y1))
        nodes.add((x2, y2))

    graph = {node: [] for node in nodes}

    for u in nodes:
        for v in nodes:
            if u != v:
                ux, uy = u
                vx, vy = v
                distance = abs(ux - vx) + abs(uy - vy)
                graph[u].append((v, distance))

    for x1, y1, x2, y2 in trenches:

        if x1 == x2:
            start_x = end_x = x1
            start_y = min(y1, y2)
            end_y = max(y1, y2)
        else:
            start_y = end_y = y1
            start_x = min(x1, x2)
            end_x = max(x1, x2)

        for x, y in nodes:
            if (start_x <= x <= end_x and start_y <= y <= end_y):
                for u in nodes:
                    if u != (x, y):
                        ux, uy = u
                        distance = abs(ux - x) + abs(uy - y)
                        graph[u].append(((x, y), distance))
                        graph[(x, y)].append((u, distance))

    distances = dijkstra(graph, (Ax, Ay))
    min_time = distances[(Bx, By)]

    if min_time == float('inf'):
        print(-1)
    else:
        wait_time = 0
        while not can_cross_laser(min_time + wait_time, a, b):
            wait_time += 1
        print(f"{min_time + wait_time:.10f}")

if __name__ == "__main__":
    main()
